"""Find all scalar subgroups in the quadratic interval generated by x and 1+x."""

import argparse
from array import array
from functools import cache
from itertools import combinations
from math import isqrt, lcm, prod

from check_scalar_order_bound import plane_degree


def smallest_factors(bound):
    table = array('I' if bound < 2**32 else 'Q', range(bound+1))
    for p in range(2, isqrt(bound)+1):
        if table[p] == p:
            for m in range(p*p,bound+1,p):
                if table[m] == m:
                    table[m] = p
    return table


def distinct_primes(n, table):
    while n > 1:
        p = table[n]
        yield p
        while n % p == 0:
            n //= p


def order_tables(limit):
    bound = (12*limit**2-1)//5
    smallest = smallest_factors(bound)
    orders = array(smallest.typecode,[0])*(bound+1)
    orders[1] = 1
    candidates = []
    for a in range(3,bound+1,2):
        p = smallest[a]
        if p == a:
            d = p-1
            for r in distinct_primes(p-1,smallest):
                while d % r == 0 and pow(2,d//r,p) == 1:
                    d //= r
        else:
            other = a
            while other % p == 0:
                other //= p
            if other > 1:
                d = lcm(orders[other],orders[a//other])
            else:
                d = orders[a//p]
                if pow(2,d,a) != 1:
                    d *= p
        orders[a] = d
        if d <= limit and 3*d*d <= 4*a and 5*a < 12*d*d:
            candidates.append((d,a))
    return smallest, orders, candidates


def survey(limit):
    smallest, orders, candidates = order_tables(limit)

    @cache
    def pair_count(a):
        if a == 1:
            return 0
        # The full nonzero group of a binary field contains all nontrivial translates.
        if a & (a+1) == 0:
            return a-1
        return plane_degree(orders[a],a)

    survivors = []
    for degree,a in sorted(candidates):
        primes = tuple(distinct_primes(a,smallest))
        # Each pair has a unique generated subgroup inside the cyclic group of order a.
        exact = sum((-1)**k*pair_count(a//prod(subset))
                    for k in range(len(primes)+1) for subset in combinations(primes,k))
        if exact < 0 or exact % degree:
            raise ArithmeticError("generated pairs must form complete Frobenius orbits")
        if exact:
            survivors.append((degree,a,exact))
    return len(candidates), survivors


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--limit",type=int,default=1000,help="largest possible degree of the plane side")
    limit = parser.parse_args().limit
    if limit < 2:
        parser.error("degree must be at least two")
    count, rows = survey(limit)
    expected = [(2,3,2),(3,7,6),(4,15,12),(5,31,30),(6,63,54),(8,85,24),(9,73,18),(12,273,24)]
    if limit == 1000 and (count != 12780 or rows != expected):
        raise ArithmeticError("composite-degree census disagrees with the published table")
    print(f"{count} candidate orders through field degree {limit}")
    print("degree,scalar_order,generating_points")
    for row in rows:
        print(*row,sep=",")
